export function loadUser(id: string): Promise<User> {
  return fetch(`/api/users/${id}`)
    .then((r) => r.json())
    .catch((err) => {
      reportError(err);
      return defaultUser();
    });
}

declare function reportError(e: unknown): void;
declare function defaultUser(): User;
interface User { id: string }

